func oiLine(lines *port.Cells, page int32, conf int32) int32 {
	var t int32 = evidence.TlNew(lines, page, 1000, 2000, 5000, 2500, 1000, 2500, 5000, 2500, 0, 0, 0, 6)
	evidence.TlSet(lines, t, evidence.TlfConf(), conf)
	evidence.TlSet(lines, t, evidence.TlfInk(), 0)
	return t
}

func TestUnreadInkKeepsSourcePageAndBoxWithoutInventedText(emonT *testing.T) {
	var lines *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	oiLine(lines, 1, 800)
	evidence.IkNew(inks, 1, 0)
	evidence.IkSet(inks, 0, evidence.IkfRole(), evidence.IrBody())
	port.CellsPush(mask, 1)
	port.AssertEq(emonT, ocrledger.OcInkAccount(lines, inks, port.NewCells(), port.NewCells(), mask, ledger, port.NewCells(), port.NewCells()), 1, "source region has no recorded reading")
	port.AssertEq(emonT, model.LedgerCount(ledger), 1, "one region, not a guessed word count")
	port.AssertEq(emonT, model.LedgerReason(ledger, 0), model.DrOcrUnreadInk(), "distinct from rejected OCR alternatives")
	port.AssertEq(emonT, model.LedgerPage(ledger, 0), 1, "source page owns the diagnostic")
	port.AssertEq(emonT, model.LedgerX0(ledger, 0), 1000, "source left")
	port.AssertEq(emonT, model.LedgerY0(ledger, 0), 2000, "source top")
	port.AssertEq(emonT, model.LedgerX1(ledger, 0), 5000, "source right")
	port.AssertEq(emonT, model.LedgerY1(ledger, 0), 2500, "source bottom")
	port.AssertEq(emonT, model.LedgerTextLen(ledger, 0), 0, "pixels supply no invented transcription")
	port.AssertEq(emonT, model.LedgerConf(ledger, 0), -1, "trace confidence is not a calibrated OCR word confidence")
}

func TestARejectedReadingIsNotUnreadSourceInk(emonT *testing.T) {
	var lines *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	oiLine(lines, 1, 800)
	evidence.IkNew(inks, 1, 0)
	evidence.IkSet(inks, 0, evidence.IkfRole(), evidence.IrBody())
	port.CellsPush(mask, 1)
	evidence.OwNew(words, 1, 1000, 2000, 5000, 2500, 1000, 2500, 5000, 2500, 0, 0, 0, 3, 0, 100, -1)
	port.AssertEq(emonT, ocrledger.OcInkAccount(lines, inks, words, port.NewCells(), mask, ledger, port.NewCells(), port.NewCells()), 0, "any recorded reading, even rejected low confidence, is OCR evidence")
	port.AssertEq(emonT, model.LedgerCount(ledger), 0, "word rejection cannot masquerade as unrecognized pixels")
}

