func TestPageRangesRetainPageOwnershipInUnorderedEvidence(emonT *testing.T) {
	var lines *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var mask *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	oiLine(lines, 1, 800)
	evidence.IkNew(inks, 1, 0)
	evidence.IkSet(inks, 0, evidence.IkfRole(), evidence.IrBody())
	port.CellsPush(mask, 1)
	port.CellsPush(mask, 1)
	evidence.OwNew(words, 1, 10000, 2000, 11000, 2500, 10000, 2500, 11000, 2500, 0, 0, 0, 3, 0, 900, -1)
	evidence.OwNew(words, 2, 1000, 2000, 5000, 2500, 1000, 2500, 5000, 2500, 0, 0, 0, 3, 0, 900, -1)
	evidence.OwNew(words, 1, 12000, 2000, 13000, 2500, 12000, 2500, 13000, 2500, 0, 0, 0, 3, 0, 900, -1)
	port.AssertEq(emonT, ocrledger.OcInkAccount(lines, inks, words, port.NewCells(), mask, ledger, port.NewCells(), port.NewCells()), 1, "interleaved foreign-page word cannot cover this trace")
	port.AssertEq(emonT, model.LedgerPage(ledger, 0), 1, "trace retains page ownership")
	evidence.OwNew(words, 1, 1000, 2000, 5000, 2500, 1000, 2500, 5000, 2500, 0, 0, 0, 3, 0, 900, -1)
	port.AssertEq(emonT, ocrledger.OcInkAccount(lines, inks, words, port.NewCells(), mask, port.NewCells(), port.NewCells(), port.NewCells()), 0, "the final same-page reading must still be considered")
}
